<script lang="ts">import type{MessageSide}from'@fex-design/core/message/types';import{messageClassName}from'@fex-design/styles/message';import{cn}from'@fex/utils';import{setContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{messageSideContextKey}from'../bubble/context';import{messageContextKey,type MessageContextValue}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{side?:MessageSide;busy?:boolean;children?:Snippet}let{side='start',busy=false,class:className,children,...rest}:Props=$props();setContext<MessageContextValue>(messageContextKey,{side:()=>side,busy:()=>busy});setContext(messageSideContextKey,()=>side)</script>
<div {...rest} data-slot="message" data-side={side} data-busy={busy?'true':'false'} aria-busy={busy} class={cn(messageClassName,className)}>{@render children?.()}</div>
